from collections import defaultdict

class DetectSquares:
    def __init__(self):
        self.points = defaultdict(int)

    def add(self, point: list[int]) -> None:
        self.points[(point[0], point[1])] += 1

    def count(self, point: list[int]) -> int:
        qx, qy = point
        ans = 0
        for (x, y), cnt in self.points.items():
            if abs(qx - x) == abs(qy - y) and abs(qx - x) > 0:
                ans += cnt * self.points[(qx, y)] * self.points[(x, qy)]
        return ans

class DetectSquares {
    map<pair<int, int>, int> points;
public:
    DetectSquares() {}

    void add(vector<int> point) {
        points[{point[0], point[1]}]++;
    }

    int count(vector<int> point) {
        int qx = point[0], qy = point[1];
        int ans = 0;
        for (const auto& [p, cnt] : points) {
            int x = p.first, y = p.second;
            if (abs(qx - x) == abs(qy - y) && abs(qx - x) > 0) {
                if (points.count({qx, y}) && points.count({x, qy})) {
                    ans += cnt * points[{qx, y}] * points[{x, qy}];
                }
            }
        }
        return ans;
    }
};

class DetectSquares {
    private Map<String, Integer> points;
    public DetectSquares() {
        points = new HashMap<>();
    }
    public void add(int[] point) {
        String key = point[0] + "," + point[1];
        points.put(key, points.getOrDefault(key, 0) + 1);
    }
    public int count(int[] point) {
        int qx = point[0], qy = point[1];
        int ans = 0;
        for (Map.Entry<String, Integer> entry : points.entrySet()) {
            String[] parts = entry.getKey().split(",");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);
            int cnt = entry.getValue();
            if (Math.abs(qx - x) == Math.abs(qy - y) && Math.abs(qx - x) > 0) {
                int c1 = points.getOrDefault(qx + "," + y, 0);
                int c2 = points.getOrDefault(x + "," + qy, 0);
                ans += cnt * c1 * c2;
            }
        }
        return ans;
    }
}

var DetectSquares = function() {
  this.points = new Map();
};

DetectSquares.prototype.add = function(point) {
  const key = `${point[0]},${point[1]}`;
  this.points.set(key, (this.points.get(key) || 0) + 1);
};

DetectSquares.prototype.count = function(point) {
  const [qx, qy] = point;
  let ans = 0;
  for (const [key, cnt] of this.points.entries()) {
    const [x, y] = key.split(',').map(Number);
    if (Math.abs(qx - x) === Math.abs(qy - y) && Math.abs(qx - x) > 0) {
      const c1 = this.points.get(`${qx},${y}`) || 0;
      const c2 = this.points.get(`${x},${qy}`) || 0;
      ans += cnt * c1 * c2;
    }
  }
  return ans;
};
